#include <stdio.h>
#include <openssl/evp.h>
int main(){unsigned char key[8]={0x13,0x34,0x57,0x79,0x9B,0xBC,0xDF,0xF1},in[8]="ABCDEFG",out[16],back[16];int n=0,m=0;EVP_CIPHER *c=EVP_CIPHER_fetch(NULL,"DES-ECB","provider=legacy");if(!c){puts("DES legacy provider unavailable in this OpenSSL installation.");return 1;}EVP_CIPHER_CTX *x=EVP_CIPHER_CTX_new();EVP_EncryptInit_ex(x,c,NULL,key,NULL);EVP_CIPHER_CTX_set_padding(x,0);EVP_EncryptUpdate(x,out,&n,in,8);EVP_EncryptFinal_ex(x,out+n,&m);printf("Ciphertext: ");for(int i=0;i<n+m;i++)printf("%02X",out[i]);puts("");EVP_DecryptInit_ex(x,c,NULL,key,NULL);EVP_CIPHER_CTX_set_padding(x,0);EVP_DecryptUpdate(x,back,&n,out,8);EVP_DecryptFinal_ex(x,back+n,&m);printf("Decrypted: %.8s\\n",back);EVP_CIPHER_CTX_free(x);EVP_CIPHER_free(c);return 0;}
